def create_default_tiers(apps, schema_editor):
    """Seed Short-term / Standard / Extended tiers and fix up existing loans.

    * Standard keeps whatever the old single "Borrowing duration" setting was (14 days by default).
    * Loans already issued keep their due date; their day count is worked out from it.
    """
    BorrowingTier = apps.get_model('library_app', 'BorrowingTier')
    LibrarySettings = apps.get_model('library_app', 'LibrarySettings')
    BorrowTransaction = apps.get_model('library_app', 'BorrowTransaction')

    old = LibrarySettings.objects.filter(pk=1).first()
    standard_days = old.borrow_period_days if old else 14
    BorrowingTier.objects.get_or_create(name='Short-term', defaults={'days': 7})
    BorrowingTier.objects.get_or_create(name='Standard', defaults={'days': standard_days, 'is_default': True})
    BorrowingTier.objects.get_or_create(name='Extended', defaults={'days': 30})

    for txn in BorrowTransaction.objects.all().only('id', 'issue_date', 'due_date'):
        days = (txn.due_date - txn.issue_date).days
        BorrowTransaction.objects.filter(pk=txn.pk).update(loan_days=max(1, min(days, 365)))


